import Foundation
import RealmSwift

final class KeyValue: EmbeddedObject { @Persisted var key: String = ""; @Persisted var value: String = "" }
final class Perk: EmbeddedObject { @Persisted var trigger: String = ""; @Persisted var effect: String = ""; @Persisted var params: String = "" }
final class AppSettings: Object { @Persisted(primaryKey: true) var id: String = "main"; @Persisted var sleepEnabled: Bool = false; @Persisted var waterEnabled: Bool = false; @Persisted var ollamaHost: String = ""; @Persisted var wallpaperAllScreens: Bool = false }
final class User: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var name: String = ""; @Persisted var phone: String = ""; @Persisted var avatarPath: String = ""; @Persisted var customFields: List<KeyValue>; @Persisted var pesetas: Int = 0; @Persisted var level: Int = 1; @Persisted var xp: Int = 0; @Persisted var debtStartedAt: Date?; @Persisted var stats: List<Stat>; @Persisted var skills: List<Skill>; @Persisted var inventory: List<Item>; @Persisted var equipped: List<Item>; @Persisted var settings: AppSettings?; static func xpForNextLevel(_ level: Int) -> Int { Int((80.0 * pow(Double(level), 1.4)).rounded(.down)) } }
final class Stat: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var name: String = ""; @Persisted var value: Int = 0; @Persisted var isDerived: Bool = false; @Persisted var parentStats: List<String> }
final class Skill: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var name: String = ""; @Persisted var isPassive: Bool = false; @Persisted var progress: Int = 0; @Persisted var linkedDailyIds: List<String> }
final class Daily: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var title: String = ""; @Persisted var statIds: List<String>; @Persisted var xpReward: Int = 0; @Persisted var pesetasReward: Int = 0; @Persisted var deadlineTime: String = "23:59"; @Persisted var streak: Int = 0; @Persisted var streakCap: Double = 2.0; @Persisted var linkedSkillId: String?; @Persisted var crystallizationDays: Int = 30; @Persisted var lastCompletedDay: Date? }
final class Event: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var title: String = ""; @Persisted var date: Date = Date(); @Persisted var type: String = "custom"; @Persisted var colorThresholdDays: Int = 10; @Persisted var linkedBossId: String?; @Persisted var linkedDailyId: String? }
final class Item: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var name: String = ""; @Persisted var rank: String = "F"; @Persisted var itemDescription: String = ""; @Persisted var imagePath: String = ""; @Persisted var costPesetas: Int = 0; @Persisted var costXp: Int = 0; @Persisted var statModifiers: Map<String, Int>; @Persisted var perks: List<Perk>; @Persisted var durability: Int = 100; @Persisted var maxDurability: Int = 100; @Persisted var acquiredAt: Date = Date(); @Persisted var isEquipped: Bool = false; @Persisted var slot: String = "" }
final class Boss: Object { @Persisted(primaryKey: true) var id: ObjectId; @Persisted var name: String = ""; @Persisted var rank: String = "F"; @Persisted var hp: Int = 100; @Persisted var requiredAttributes: List<String>; @Persisted var orderIndex: Int?; @Persisted var calendarEventLink: String?; @Persisted var rewardsPesetas: Int = 0; @Persisted var rewardsXp: Int = 0; @Persisted var pixelArtAscii: String = ""; @Persisted var isDefeated: Bool = false }
